package com.fasterxml.jackson.databind.node;

import com.fasterxml.jackson.core.*;
import com.fasterxml.jackson.core.JsonParser;
import com.fasterxml.jackson.core.JsonToken;
import com.fasterxml.jackson.core.base.ParserMinimalBase;
import com.fasterxml.jackson.databind.JsonNode;
import com.fasterxml.jackson.databind.ObjectMapper;
import com.fasterxml.jackson.databind.node.NumericNode;
import com.fasterxml.jackson.databind.node.ObjectNode;
import com.fasterxml.jackson.databind.node.TextNode;
import java.io.*;
import java.io.IOException;
import java.io.OutputStream;
import java.math.*;
import java.math.BigDecimal;
import java.math.BigInteger;
import java.util.*;
import org.junit.*;
import org.junit.Assert;
import org.junit.Before;
import org.junit.Test;
import static org.junit.Assert.*;

public class TreeTraversingParser_getLongValue_TriageGen0Test {

    private ObjectMapper mapper;

    @Before
    public void setUp() {
        mapper = new ObjectMapper();
    }

    /**
     * Tests getLongValue when the current node is a valid Long NumericNode.
     * This covers the main success path.
     */
    @Test
    public void testGetLongValue_Success() throws IOException {
        ObjectNode root = mapper.createObjectNode();
        root.putLong("val", 123456789L);

        TreeTraversingParser parser = new TreeTraversingParser(root);

        // Move to the field "val"
        parser.nextToken(); // START_OBJECT
        parser.nextToken(); // FIELD_NAME "val"
        parser.nextToken(); // VALUE_NUMBER_INT 123456789

        long result = parser.getLongValue();

        Assert.assertEquals(123456789L, result);
    }

    /**
     * Tests getLongValue with the maximum possible long value.
     */
    @Test
    public void testGetLongValue_MaxLong() throws IOException {
        ObjectNode root = mapper.createObjectNode();
        root.put("val", Long.MAX_VALUE);

        TreeTraversingParser parser = new TreeTraversingParser(root);

        parser.nextToken(); // START_OBJECT
        parser.nextToken(); // FIELD_NAME
        parser.nextToken(); // VALUE_NUMBER_INT

        long result = parser.getLongValue();

        Assert.assertEquals(Long.MAX_VALUE, result);
    }

    /**
     * Tests getLongValue when the current node is not a NumericNode.
     * This targets the cast (NumericNode) currentNumericNode() which will throw ClassCastException.
     */
    @Test(expected = ClassCastException.class)
    public void testGetLongValue_NotANumericNode() throws IOException {
        ObjectNode root = mapper.createObjectNode();
        root.put("val", "not a number");

        TreeTraversingParser parser = new TreeTraversingParser(root);

        parser.nextToken(); // START_OBJECT
        parser.nextToken(); // FIELD_NAME
        parser.nextToken(); // VALUE_STRING "not a number"

        // This should trigger ClassCastException because currentNumericNode() 
        // will return a TextNode instead of a NumericNode
        parser.getLongValue();
    }

    /**
     * Tests getLongValue when the current node is null or doesn't exist.
     * This verifies behavior when attempting to read value without being on a token.
     */
    @Test(expected = Exception.class)
    public void testGetLongValue_NoCurrentNode() throws IOException {
        ObjectNode root = mapper.createObjectNode();
        root.put("val", 100L);

        TreeTraversingParser parser = new TreeTraversingParser(root);

        // We don't call nextToken(), so currentNumericNode() will likely fail or return null
        parser.getLongValue();
    }
}
